import {cms} from '@/cms'
import {formFiles} from 'alinea/backend'
import {createHandler} from 'alinea/next'
import {Resend} from 'resend'

const resend = new Resend(process.env.RESEND_API_KEY)

const handler = createHandler({
  cms,
  forms: {
    mailer: mail =>
      resend.emails.send({from: 'My site <forms@example.com>', ...mail}),
    files: formFiles.s3({
      bucket: 'my-site-form-files',
      region: 'eu-west-1',
      accessKeyId: process.env.S3_ACCESS_KEY_ID!,
      secretAccessKey: process.env.S3_SECRET_ACCESS_KEY!
    }),
    limits: {submissions: 10, uploads: 20}
  }
})

export const GET = handler
export const POST = handler
// Visitors upload the files of forms with PUT requests
export const PUT = handler

import {cms} from '@/cms'
import {createHandler} from 'alinea/next'
import {Pool} from 'pg'

const handler = createHandler({
  cms,
  forms: {
    database: {
      driver: 'pg',
      client: new Pool({connectionString: process.env.DATABASE_URL})
    }
  }
})

export const GET = handler
export const POST = handler
export const PUT = handler

'use server'

import {cms} from '@/cms'
import {verifyCaptcha} from '@/captcha'

export async function submitForm(entryId: string, data: FormData) {
  return cms.forms.submit(entryId, data, {
    verify: () => verifyCaptcha(data.get('captcha-token'))
  })
}

const handler = createHandler({
  cms,
  forms: {
    async onSubmit({submission, title}) {
      await fetch(process.env.CRM_WEBHOOK_URL!, {
        method: 'POST',
        headers: {'content-type': 'application/json'},
        body: JSON.stringify({form: title, answers: submission.values})
      })
    }
  }
})
